        let bitsInputs = Inputs.shiftAmounts(bits: 64, inContract: true)
        mismatches.check(
            H.repeating(value),
            H.Vector(raw: HighwayReference.repeatingU64(value)),
            "repeating"
        )
        for bits in bitsInputs {
            mismatches.check(
                H.rotatedLeft(H.repeating(value), by: bits),
                H.Vector(
                    raw: HighwayReference.rotatedLeftU64(
                        H.repeating(value).raw,
                        Int32(clamping: bits)
                    )
                ),
                "bits: \(bits)"
            )
        }
        mismatches.record()
    }

    @Test func rotatedLeftConstantSplat0() {
        checkRotatedLeftConstantA(0)
    }

    @Test func rotatedLeftConstantSplat1() {
        checkRotatedLeftConstantA(1)
    }

    @Test func rotatedLeftConstantSplat15() {
        checkRotatedLeftConstantA(15)
    }

    @Test func rotatedLeftConstantSplat16() {
        checkRotatedLeftConstantA(16)
    }

